CREATE SEQUENCE my_seq;
SELECT nextval('my_seq');  -- advances and returns
SELECT currval('my_seq');  -- last value this session got, no advance

BEGIN;
SELECT nextval('my_seq'); -- returns 5
ROLLBACK;
SELECT nextval('my_seq'); -- returns 6, not 5 again

CREATE TABLE employees (id int, name text);
CREATE TABLE managers (bonus numeric) INHERITS (employees);
SELECT * FROM employees;        -- includes managers rows too
SELECT * FROM ONLY employees;   -- excludes managers rows

